const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const norma = a => a === EM ? 'exposición de motivos de la Ley Orgánica 18/2003' : `${a} de la Ley Orgánica 18/2003`;
const expl = (letra, ok, a, t, p, ia) => `<span class="ex-resp">Respuesta correcta: <b>${letra}</b> · <mark class="ex-key">${esc(ok.replace(/\.$/, ''))}</mark></span>${a === EM ? 'La' : 'El'} <span class="ref-norma">${norma(a)}</span> dispone: <span class="ref-concepto">"${esc(t)}"</span>. ${esc(p)}${ia ? ' <em style="color:var(--texto-gris)">(Pregunta generada por IA)</em>' : ''}`;
const uso = { 0: 0, 1: 0, 2: 0, 3: 0 };
Q.forEach(q => { if (q.c !== null) uso[q.c]++; });
const ia = Q.map((q, i) => {
  let ops = q.o.slice(), c = q.c;
  if (c === null) { const ok = ops.shift(); c = [0, 1, 2, 3].sort((a, b) => uso[a] - uso[b] || ((a + i) % 4) - ((b + i) % 4))[0]; ops.splice(c, 0, ok); uso[c]++; }
  return { id: '1-ia-' + (1001 + i), pregunta: `${N} ${q.r}. ${q.e}`, opciones: ops, correcta: c, dificultad: 'media',
    explicacion: expl(L[c], ops[c], q.a, q.t, q.p, true), apartado: AP };
});
const of = OF.map(q => ({ id: q.id, pregunta: `${N} ${q.r}. ${q.e}`, opciones: q.o, correcta: q.c, explicacion: expl(L[q.c], q.o[q.c], q.a, q.t, q.p, false), apartado: AP }));

const arg = process.argv.slice(2);
if (arg[0] === '--json') { fs.writeFileSync(arg[1], JSON.stringify(ia, null, 1)); fs.writeFileSync(arg[1].replace(/\.json$/, '-of.json'), JSON.stringify(of, null, 1)); console.log(ia.length, 'IA +', of.length, 'oficiales · letras', JSON.stringify(uso)); process.exit(0); }

let s = fs.readFileSync(F, 'utf8');
const BS = '\\';
const rango = id => { const k = '{"id":"' + id + '"'; const i = s.indexOf(k); if (i < 0) return null; let d = 0, inS = false, e = false, j = i; for (; j < s.length; j++) { const ch = s[j]; if (inS) { if (e) e = false; else if (ch === BS) e = true; else if (ch === '"') inS = false; continue; } if (ch === '"') inS = true; else if (ch === '{') d++; else if (ch === '}') { d--; if (d === 0) break; } } return [i, j + 1]; };
// 1) oficiales: reescribir / añadir
for (const o of of) { const r = rango(o.id); if (r) s = s.slice(0, r[0]) + JSON.stringify(o) + s.slice(r[1]); else { const p = rango('1-130'); s = s.slice(0, p[1]) + ',' + JSON.stringify(o) + s.slice(p[1]); } }
// 2) citas literales en oficiales sin cita
for (const [id, [a, t]] of Object.entries(CITAS)) { const r = rango(id); const q = JSON.parse(s.slice(r[0], r[1])); if (/ref-concepto/.test(q.explicacion)) continue; const cab = q.explicacion.match(/^<span class="ex-resp">[\s\S]*?<\/span>/)[0]; q.explicacion = `${cab}El <span class="ref-norma">${a} de la Ley Orgánica 18/2003</span> dispone: <span class="ref-concepto">"${esc(t)}"</span>.`; s = s.slice(0, r[0]) + JSON.stringify(q) + s.slice(r[1]); }
// 3) borrar IA antiguas de la LO 18/2003 (1-ia-1…75 y 1-ia-226…278)
const viejas = []; for (let n = 1; n <= 75; n++) viejas.push('1-ia-' + n); for (let n = 226; n <= 278; n++) viejas.push('1-ia-' + n);
let borradas = 0;
for (const id of viejas) { const r = rango(id); if (!r) continue; let [a, b] = r; if (s[b] === ',') b++; else if (s[a - 1] === ',') a--; s = s.slice(0, a) + s.slice(b); borradas++; }
s = s.replace('(function(){const seed=[];syncSeedIA(1,seed)})();', '');
// 4) nuevo bloque semilla + purga de IA del tema 1 que ya no están en ninguna semilla (también del localStorage)
const PURGA = '(function(){const S=window.__seedIdsIA||{};const P=(state.preguntasIA||{})[1];if(!P)return;const n=P.length;state.preguntasIA[1]=P.filter(q=>!(q&&/^1-ia-\\d+$/.test(q.id)&&!S[q.id]));state.preguntasIA[1].length!==n&&saveState()})();';
if (!s.includes('"id":"1-ia-1001"')) {
  const m = '];syncSeedIA(1,seed)})();'; let k = -1, p = -1; let i0 = s.indexOf('{"id":"1-ia-'); // último bloque del tema 1
  while ((k = s.indexOf(m, k + 1)) >= 0) { const ini = s.lastIndexOf('(function(){const seed=[', k); if (s.slice(ini, k).includes('"id":"1-ia-')) p = k + m.length; }
  if (p < 0) throw new Error('bloque del tema 1 no encontrado');
  s = s.slice(0, p) + '(function(){const seed=' + JSON.stringify(ia) + ';syncSeedIA(1,seed)})();' + (s.includes(PURGA) ? '' : PURGA) + s.slice(p);
}
fs.writeFileSync(F, s);
console.log('IA antiguas borradas', borradas, '· IA nuevas', ia.length, '· oficiales', of.length, '· citas añadidas', Object.keys(CITAS).length);
